package com.minecraft.arcade.pvp.user.factory.list;import com.minecraft.arcade.pvp.arcade.arena.Arena;import com.minecraft.arcade.pvp.arcade.list.arena.objects.controller.KitController;import com.minecraft.arcade.pvp.arcade.list.arena.objects.kit.Kit;import com.minecraft.arcade.pvp.arcade.list.arena.objects.kit.enums.KitCategory;import com.minecraft.arcade.pvp.user.User;import com.minecraft.core.arcade.route.join.Join;import com.minecraft.core.member.list.pvp.PvPMember;import com.minecraft.core.member.list.pvp.stats.list.ArenaStats;import lombok.Getter;import lombok.Setter;@Getter@Setterpublic class ArenaUser extends User {    private Kit primary, secondary;    public ArenaUser(PvPMember member, Arena arena, Join join) {        super(member, arena, join);        this.primary = KitController.empty();        this.secondary = KitController.empty();    }    public ArenaStats getStats() {        return getMember().getArenaStats();    }    public Kit getKit(KitCategory category) {        return category.equals(KitCategory.PRIMARY) ? primary : secondary;    }    public boolean hasPrimary() {        return primary != null;    }    public boolean isNotUsingKit() {        return hasPrimary() && primary.isEmpty() && hasSecondary() && secondary.isEmpty();    }    public boolean hasSecondary() {        return secondary != null;    }    public boolean isUsingKit(Class<? extends Kit> kitClass) {        return hasPrimary() && kitClass.isAssignableFrom(primary.getClass()) || hasSecondary() && kitClass.isAssignableFrom(secondary.getClass());    }    public boolean isUsingKit(Kit kit) {        if (kit.isEmpty() && hasPrimary() && primary.equals(kit)) return true;        return isUsingKit(kit.getClass());    }    public boolean isUsingKit(Kit kit, KitCategory category) {        if (kit.isEmpty() && category.equals(KitCategory.PRIMARY) && hasPrimary() && !primary.equals(kit)) return false;        if (kit.isEmpty() && category.equals(KitCategory.SECONDARY) && hasSecondary() && !secondary.equals(kit)) return false;        return isUsingKit(kit);    }}